const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('hub-back').hidden=!location.pathname.startsWith('/infra-lab/');
let state,selected=null,selectedLink=null,menuPoint={x:40,y:60},toastTimer;
try{const raw=localStorage.getItem('infra-lab-v1');if(raw){const parsed=JSON.parse(raw);if(parsed.nodes?.some(n=>n.type==='k8s_node'&&!n.services.kubernetes?.controlModel))try{if(!localStorage.getItem('infra-lab-backup-before-runtime-control'))localStorage.setItem('infra-lab-backup-before-runtime-control',raw)}catch{}if(parsed.nodes?.some(n=>n.type==='container'&&!n.applicationModel)&&!localStorage.getItem('infra-lab-backup-before-applications'))localStorage.setItem('infra-lab-backup-before-applications',raw);if(parsed.demoRevision===3)try{localStorage.setItem('infra-lab-backup-before-trace',raw)}catch{}if(!parsed.schemaVersion)try{localStorage.setItem('infra-lab-backup-before-engine-v2',raw)}catch{}state=validate(parsed)}else state=demo()}catch{state=demo()}
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',5000)}
function save(){try{localStorage.setItem('infra-lab-v1',JSON.stringify(state));$('save').textContent='Сохранено на этом устройстве'}catch{$('save').textContent='Сохранение недоступно — экспортируйте JSON'}}
function change(){provisionControl(state,create);cleanupControl(state);cleanupWorkloads(state);settle(state);player.invalidate(state);const current=JSON.stringify(state);if(current!==lastState){history.push(lastState);future.length=0;if(history.length>30)history.shift();lastState=current}save();render()}
const history=[],future=[];let lastState=JSON.stringify(state);
function restoreHistory(from,to,message){if(!from.length)return toast('Нет действий для '+(from===history?'отмены':'повтора'));to.push(JSON.stringify(state));$('menu').hidden=true;canvas.removePointTarget=null;state=validate(JSON.parse(from.pop()));selected=null;selectedLink=null;canvas.pending=null;canvas.selectedLink=null;canvas.selection.clear();settle(state);lastState=JSON.stringify(state);player.invalidate(state);save();render();toast(message)}
function undo(){restoreHistory(history,future,'Действие отменено')}
function redo(){restoreHistory(future,history,'Действие повторено')}
async function confirmAction(message){const dialog=$('confirm-dialog');$('confirm-message').textContent=message;dialog.showModal();return new Promise(resolve=>{dialog.onclose=()=>resolve(dialog.returnValue==='yes')})}
const canvas=new LabCanvas({getState:()=>state,getSelected:()=>selected,commit:change,notify:toast,
selectNodes:ids=>{selected=ids.length===1?ids[0]:null;selectedLink=null;canvas.selectedLink=null;$('selection-count').textContent=ids.length>1?'Выделено: '+ids.length:'';tab('inspect');renderInspect()},
selectNode:id=>{canvas.selection=new Set([id]);selected=id;selectedLink=null;canvas.selectedLink=null;tab('inspect');renderInspect()},
selectLink:id=>{canvas.selection.clear();selectedLink=id;selected=null;tab('inspect');renderInspect()}});
installTrafficCanvas(canvas);try{canvas.controlVisible=localStorage.getItem('infra-lab-control-links')!=='false'}catch{}$('control-links').setAttribute('aria-pressed',String(canvas.controlVisible));$('control-links').onclick=()=>{canvas.controlVisible=!canvas.controlVisible;try{localStorage.setItem('infra-lab-control-links',String(canvas.controlVisible))}catch{}$('control-links').setAttribute('aria-pressed',String(canvas.controlVisible));canvas.render()};const player=new TrafficPlayer(canvas,()=>state);canvas.pauseTraffic=()=>player.pause();canvas.logicalView=new LogicalNetworkView(()=>state,canvas,player);canvas.viewport.tabIndex=0;$('vlan-colors').setAttribute('aria-pressed',canvas.vlanColors);$('vlan-colors').onclick=()=>{canvas.vlanColors=!canvas.vlanColors;localStorage.setItem('infra-lab-vlan-colors',canvas.vlanColors);$('vlan-colors').setAttribute('aria-pressed',canvas.vlanColors);canvas.render()};
function addInterface(n,preset){const action=interfaceAction(n);if(!action.enabled){toast(action.reason);return false}if(action.attach){toast(action.reason);tab('inspect');renderInspect();$('inspect').querySelector('.member-choice')?.scrollIntoView({block:'center'});return false}try{const count=PASSIVE.includes(n.type)?n.interfaces.length%2?1:2:1;for(let i=0;i<count;i++)iface(n,{state,preset});return true}catch(err){toast(err.message);return false}}
function removeNodes(requested){const ids=new Set(requested);let old;do{old=ids.size;state.nodes.filter(n=>ids.has(n.parent)).forEach(n=>ids.add(n.id))}while(old!==ids.size);const ports=new Set(state.nodes.filter(n=>ids.has(n.id)).flatMap(n=>n.interfaces.map(p=>p.id)));state.nodes=state.nodes.filter(n=>!ids.has(n.id));state.links=state.links.filter(l=>!ports.has(l.a)&&!ports.has(l.b));state.nodes.forEach(n=>{if(n.members)n.members=n.members.filter(id=>!ports.has(id));if(n.services.http&&ids.has(n.services.http.publishHost))n.services.http.publishHost=''});selected=null;selectedLink=null;canvas.selectedLink=null;canvas.pending=null;canvas.selection.clear();$('selection-count').textContent='';$('menu').hidden=true;change()}
function children(id){return state.nodes.filter(n=>n.parent===id)}
function layout(n){return geometry(state).sizes.get(n.id)||{w:300,h:120}}
function abs(n){return geometry(state).rects.get(n.id)||{x:0,y:0}}
function renderBoard(){canvas.render()}
function drawWires(){canvas.render()}
function render(){$('selection-count').textContent=canvas.selection.size>1?'Выделено: '+canvas.selection.size:'';try{$('restore-backup').hidden=!localStorage.getItem('infra-lab-backup-before-demo')}catch{}$('demo-guide').hidden=!state.demoGuide;$('cluster-policy').hidden=![5,6].includes(state.demoRevision);$('demo-check').textContent='▷ Проверить сайт '+(state.demoRequest?.target||'site.lab')+':'+(state.demoRequest?.port||8080);$('demo-path').innerHTML=(state.demoGuide||[]).map(x=>'<li>'+esc(x)+'</li>').join('');renderBoard();$('count').textContent=state.nodes.length;$('summary').textContent=`${state.nodes.length} объектов · ${state.links.length} кабелей · ${bindings(state).length} привязок`;$('tree').innerHTML='';const item=(n,depth)=>{$('tree').insertAdjacentHTML('beforeend',`<button class="treeitem ${selected===n.id?'selected':''}" data-select="${n.id}" style="padding-left:${7+depth*10}px">${TYPES[n.type][1]} &nbsp; ${esc(n.name)}</button>`);children(n.id).forEach(k=>item(k,depth+1))};children(null).forEach(n=>item(n,0));renderInspect();const value=$('source').value;$('source').innerHTML=state.nodes.filter(n=>hostInterfaces(state,n.id).length&&!bridgeTypes.includes(n.type)).map(n=>`<option value="${n.id}">${esc(n.name)}</option>`).join('');$('source').value=state.nodes.some(n=>n.id===value)?value:state.nodes.find(n=>n.type==='client')?.id||$('source').options[0]?.value;const issues=diagnostics(state);$('issues').innerHTML=issues.length?issues.map(i=>`<div class="issue">⚠ ${esc(i)}</div>`).join(''):'<span class="pill">✓ Конфликтов адресации нет</span>'}
function helpHTML(n){const h=HELP[n.type];return '<div class="help-card">'+(n.type==='bridge'&&interfaceOwner(state,n).id!==n.id?'<p>Linux-мост ядра хоста <b>'+esc(interfaceOwner(state,n).name)+'</b>. Вложенность под Docker обозначает управление сетью.</p>':'')+'<b>'+esc(h.role)+'</b><p>'+esc(h.text)+'</p><details><summary>Пример и интерфейсы</summary><p>'+esc(h.example)+'</p><p>'+esc(h.interfaces)+'</p></details></div>'}
function membershipHTML(n){if(n.type!=='bridge')return '';const candidates=bridgeCandidates(state,n);return '<div class="section">УЧАСТНИКИ МОСТА</div><p>Это внутренняя привязка: внешний кабель адаптера сохраняется. Сиреневый пунктир — связь с мостом.</p>'+ (candidates.length?candidates.map(({node,p})=>{const other=state.nodes.find(b=>b.type==='bridge'&&b.id!==n.id&&b.members?.includes(p.id));return '<label class="member-choice"><input type="checkbox" data-member="'+p.id+'" '+(n.members?.includes(p.id)?'checked ':'')+(other?'disabled ':'')+'><span>'+esc(node.name)+' / '+esc(p.name)+'<small>'+esc(other?'Уже в мосту '+other.name:(p.kind==='physical'?'Физический':'Виртуальный')+' · '+(p.ip||'без IP'))+'</small></span></label>'}).join(''):'<div class="hint">Сначала добавьте интерфейс хосту, ВМ или контейнеру. В области этого моста пока нет подходящих адаптеров.</div>')}
function field(label,key,value,type='text'){return `<label>${label}<input data-key="${key}" type="${type}" value="${esc(value)}"></label>`}
function renderInspect(){if(canvas.selection.size>1){$('inspect').innerHTML='<div class="eyebrow">ГРУППОВОЕ ВЫДЕЛЕНИЕ</div><h2>'+canvas.selection.size+' объектов</h2><p>Тяните за заголовок любого выделенного объекта. Коллизии и вложенность сохраняются.</p><div class="selection-list">'+state.nodes.filter(n=>canvas.selection.has(n.id)).map(n=>'<div>'+esc(TYPES[n.type][1]+' '+n.name)+'</div>').join('')+'</div><button id="delete-selection" class="delete">Удалить выделенные объекты</button><button id="clear-selection" style="margin-top:10px;width:100%">Снять выделение · Esc</button>';return}if(selectedLink){const l=state.links.find(l=>l.id===selectedLink);if(l){$('inspect').innerHTML=connectionInspector(state,l,canvas.lag);return}selectedLink=null}const n=state.nodes.find(n=>n.id===selected);if(!n){$('inspect').innerHTML='<div class="eyebrow">ВАША ЛАБОРАТОРИЯ</div><h2>Начните с кабеля.</h2><p>Демонстрационная сеть уже собрана. Выберите объект, чтобы настроить интерфейсы и службы.</p><div class="hint"><b>Сайт в контейнере / Pod</b><br>Клиент → коммутатор → сервер → ВМ → сетевое ядро ОС → мост → контейнер / Pod → приложение.<br>Для текущего демо используйте кнопку «Проверить сайт» в инструкции над холстом.<br><br>Откройте «Проверка сети» и отправьте запрос к <b>site.lab</b>.</div><div class="hint">Нажмите правой кнопкой по свободному месту для создания стойки, клиента или сетевого оборудования. По объекту — для действий внутри него.</div>';return}$('inspect').innerHTML=`<div class="eyebrow">${esc(TYPES[n.type][0])}</div><h2>${esc(n.name)}</h2>${helpHTML(n)}${field('Название','name',n.name)}<button id="context-action" style="margin-top:12px;width:100%">＋ Действия с объектом</button>${membershipHTML(n)}<div class="section">СЕТЕВЫЕ ИНТЕРФЕЙСЫ <button id="add-port" title="${esc(interfaceAction(n).reason)}" ${interfaceAction(n).enabled?'':'disabled'}>${interfaceAction(n).label}</button></div>${n.interfaces.map(p=>`<details class="interface" data-interface="${p.id}" ${n.interfaces.length<=2?'open':''}>${interfaceSummary(state,n,p,canvas.lag)}${field('Имя интерфейса','name',p.name)}${physicalHTML(n,p)}<label>Тип адаптера<select data-key="kind"><option value="physical" ${allowedInterfaceProfiles(n,p).some(k=>k!=='virtual')?'':'disabled'} ${p.kind==='physical'?'selected':''}>Физический</option><option value="virtual" ${allowedInterfaceProfiles(n,p).includes('virtual')?'':'disabled'} ${p.kind==='virtual'?'selected':''}>Виртуальный</option></select></label><label>Режим<select data-key="mode"><option value="auto" ${p.mode==='auto'?'selected':''}>Автоматически</option><option value="manual" ${p.mode==='manual'?'selected':''}>Вручную</option></select></label>${field('Адрес интерфейса','ip',p.ip)}<div class="row">${field('Префикс','prefix',p.prefix,'number')}${field('Шлюз','gateway',p.gateway)}</div>${field('DNS-сервер','dns',p.dns)}<button data-disconnect="${p.id}" style="margin-top:10px" ${state.links.some(l=>l.a===p.id||l.b===p.id)?'':'disabled'}>Отключить кабель</button></details>`).join('')||'<p>'+esc(interfaceAction(n).enabled?'Нет интерфейсов. Добавьте контакт при необходимости.':interfaceAction(n).reason)+'</p>'}${servicesHTML(n)}${workloadHTML(state,n)}${controlUI(state,n)}<button id="delete-node" class="delete">Удалить объект и содержимое</button><div class="hint">Правки применяются после выхода из поля. Авто IP — учебный планировщик; DHCP требует сервера в том же L2-сегменте.</div>`}
function servicesHTML(n){let html='';if(n.type==='dhcp'){const d=n.services.dhcp;html+=`<div class="section">DHCP · ПУЛ СЕГМЕНТА</div>${field('Подсеть (CIDR)','dhcp.cidr',d.cidr)}<div class="row">${field('Начальный хост','dhcp.start',d.start,'number')}${field('Конечный хост','dhcp.end',d.end,'number')}</div>${field('Шлюз для клиентов','dhcp.gateway',d.gateway)}${field('DNS для клиентов','dhcp.dns',d.dns)}<label>Служба<select data-key="dhcp.enabled"><option value="true" ${d.enabled?'selected':''}>Включена</option><option value="false" ${!d.enabled?'selected':''}>Выключена</option></select></label>`}if(n.type==='dns')html+=`<div class="section">DNS · A-ЗАПИСИ</div><label>JSON: имя → IPv4<textarea data-key="dns.records">${esc(JSON.stringify(n.services.dns.records,null,2))}</textarea></label><label>Служба<select data-key="dns.enabled"><option value="true" ${n.services.dns.enabled?'selected':''}>Включена</option><option value="false" ${!n.services.dns.enabled?'selected':''}>Выключена</option></select></label>`;if(n.type==='firewall')html+=`<div class="section">ПРАВИЛА ПЕРЕСЫЛКИ</div><label>ICMP<select data-key="blockICMP"><option value="false" ${!n.rules.blockICMP?'selected':''}>Разрешить</option><option value="true" ${n.rules.blockICMP?'selected':''}>Запретить</option></select></label>${field('Запретить TCP-порты (через запятую)','blockedPorts',n.rules.blockedPorts.join(','))}<p>Остальной транзит разрешён. Правила действуют при прохождении через этот фаервол.</p>`;if(n.type==='container'){const h=n.services.http;html+=`<div class="section">ПУБЛИКАЦИЯ ПОРТА КОНТЕЙНЕРА</div>${field('Целевой порт приложения','http.port',h.port,'number')}<label>Хост публикации<select data-key="http.publishHost"><option value="">Не публиковать</option>${state.nodes.filter(a=>osTypes.includes(a.type)).map(a=>`<option value="${a.id}" ${h.publishHost===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>${field('Порт на хосте','http.publishPort',h.publishPort,'number')}<p>Контейнер соединяется veth-парой с ядром Ubuntu. Хостовый конец присоединяется к Linux-мосту; IP шлюза принадлежит мосту. Публикация порта выполняется ядром хоста.</p>`}return html}
function menu(parent,x,y){const n=state.nodes.find(n=>n.id===parent),types=CHILDREN[n?.type||'root']||[];$('menu').innerHTML=`<div class="menutitle">${esc(n?.name||'Холст')} · ДОБАВИТЬ</div>${types.map(t=>`<button data-create="${t}" data-parent="${parent||''}">${TYPES[t][1]} &nbsp; ${TYPES[t][0]}</button>`).join('')}${n?'<button '+(interfaceAction(n).enabled?'':'disabled ')+'title="'+esc(interfaceAction(n).reason)+'" data-add-interface="'+n.id+'">'+esc(interfaceAction(n).label)+'</button>'+(['ubuntu','debian','proxmox'].includes(n.type)?'<button data-add-veth="'+n.id+'">＋ veth · виртуальный интерфейс Linux</button>':'')+'<button data-toggle="'+n.id+'">↕ Свернуть / развернуть</button>':''}${!types.length?'<div class="menutitle">Вложенные объекты не поддерживаются</div>':''}`;$('menu').hidden=false;$('menu').style.left=Math.min(x,innerWidth-250)+'px';$('menu').style.top=Math.max(8,Math.min(y,innerHeight-320))+'px'}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#menu,#add,#context-action'))$('menu').hidden=true},true);
document.addEventListener('contextmenu',e=>{if(!e.target.closest('main'))return;e.preventDefault();if(e.target.closest('#viewport')&&!e.target.closest('.node,[data-route-key],[data-route-handle],button')&&canvas.cancelActiveAction()){$('menu').hidden=true;return}let contact=e.target.closest('[data-port]');if(!contact&&e.target.closest('[data-link],[data-binding]')){let distance=9;for(const el of canvas.host.querySelectorAll('[data-port]')){const r=el.querySelector('.port-dot').getBoundingClientRect(),d=Math.hypot(e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2);if(d<distance){distance=d;contact=el}}}if(contact){const id=contact.dataset.port,n=state.nodes.find(n=>n.interfaces.some(p=>p.id===id)),p=n?.interfaces.find(p=>p.id===id);if(n&&p){$('menu').innerHTML='<div class="menutitle">'+esc(n.name+' / '+portView(n,p).name)+'</div><button data-inspect-interface="'+esc(id)+'">Свойства интерфейса</button><button data-remove-interface="'+esc(id)+'">× '+(PASSIVE.includes(n.type)?'Удалить пару PORT '+esc(p.pairIndex||Math.floor(n.interfaces.indexOf(p)/2)+1)+' IN / OUT':'Удалить интерфейс')+'</button><div class="menutitle">Связанные кабели и привязки тоже удалятся. ↶ — отменить.</div>';$('menu').hidden=false;$('menu').style.left=Math.max(8,Math.min(e.clientX,innerWidth-280))+'px';$('menu').style.top=Math.max(8,Math.min(e.clientY,innerHeight-180))+'px';return}}const link=e.target.closest('[data-link]');if(link){$('menu').innerHTML=`<button data-remove-link="${link.dataset.link}">× Удалить кабель</button>`;$('menu').hidden=false;$('menu').style.left=Math.min(e.clientX,innerWidth-250)+'px';$('menu').style.top=e.clientY+'px';return}const n=e.target.closest('.node');const w=$('world').getBoundingClientRect();menuPoint={x:Math.max(20,(e.clientX-w.left)/canvas.zoom),y:Math.max(30,(e.clientY-w.top)/canvas.zoom)};menu(n?.dataset.id,e.clientX,e.clientY)});
document.addEventListener('click',e=>{if(e.target.dataset.removeInterface){const result=removeInterface(state,e.target.dataset.removeInterface);$('menu').hidden=true;selected=result.nodeId;selectedLink=null;canvas.selectedLink=null;canvas.pending=null;canvas.selection=new Set([selected]);change();toast('Удалено: '+result.name+' · кабелей: '+result.cables+' · привязок: '+result.bindings+'. ↶ — отменить');return}if(e.target.dataset.inspectInterface){const id=e.target.dataset.inspectInterface,n=state.nodes.find(n=>n.interfaces.some(p=>p.id===id));selected=n.id;selectedLink=null;canvas.selectedLink=null;canvas.selection=new Set([selected]);$('menu').hidden=true;tab('inspect');render();const field=[...$('inspect').querySelectorAll('[data-interface]')].find(el=>el.dataset.interface===id);if(field){field.open=true;field.scrollIntoView({block:'center',behavior:'smooth'})}return}
if(e.target.dataset.addVeth){const n=state.nodes.find(n=>n.id===e.target.dataset.addVeth);if(addInterface(n,'veth')){selected=n.id;change();tab('inspect')}$('menu').hidden=true;return}if(e.target.dataset.addInterface){const n=state.nodes.find(n=>n.id===e.target.dataset.addInterface);if(n.interfaces.length>=32){toast('Максимум 32 интерфейса');return}selected=n.id;if(!addInterface(n)){$('menu').hidden=true;return}selected=n.id;selectedLink=null;change();tab('inspect');$('menu').hidden=true;return}const createBtn=e.target.closest('[data-create]');if(createBtn){const parent=createBtn.dataset.parent||null,n=create(createBtn.dataset.create,parent,parent?24:menuPoint.x,parent?90:menuPoint.y,{state});if(parent){const sib=children(parent);n.y=sib.length?Math.max(...sib.map(a=>a.y+layout(a).h))+24:100;const p=state.nodes.find(n=>n.id===parent);p.collapsed=false}state.nodes.push(n);selected=n.id;selectedLink=null;change();canvas.focus(n.id);tab('inspect');$('menu').hidden=true;return}if(e.target.dataset.toggle){const n=state.nodes.find(n=>n.id===e.target.dataset.toggle);n.collapsed=!n.collapsed;$('menu').hidden=true;change();return}if(e.target.dataset.removeLink){$('menu').hidden=true;state.links=state.links.filter(l=>l.id!==e.target.dataset.removeLink);selectedLink=null;canvas.selectedLink=null;canvas.pending=null;change();return}if(e.target.closest('.collapse')){const n=state.nodes.find(n=>n.id===e.target.closest('.node').dataset.id);n.collapsed=!n.collapsed;change();return}const select=e.target.closest('[data-select]');if(select){canvas.selectedWireRoute=null;selected=select.dataset.select;canvas.selection=new Set([selected]);selectedLink=null;canvas.selectedLink=null;let n=state.nodes.find(n=>n.id===selected);while(n.parent){n=state.nodes.find(a=>a.id===n.parent);n.collapsed=false}change();canvas.focus(selected);tab('inspect');return}
const n=e.target.closest('.node');if(n){if(canvas.selection.size>1&&canvas.selection.has(n.dataset.id))return;selected=n.dataset.id;canvas.selection=new Set([selected]);selectedLink=null;canvas.selectedLink=null;tab('inspect');renderInspect();document.querySelectorAll('.node').forEach(el=>el.classList.toggle('selected',el.dataset.id===selected))}if(!e.target.closest('#menu,#add,#context-action'))$('menu').hidden=true;});
const editingText=e=>e.target.closest?.('input,textarea,select,[contenteditable="true"]');
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('menu').hidden=true;if(editingText(e)||!(e.ctrlKey||e.metaKey))return;const key=e.key.toLowerCase();if(key==='z'||key==='y'){e.preventDefault();if(canvas.cancelActiveAction())return;if(key==='y'||e.shiftKey)redo();else undo()}});
document.addEventListener('copy',e=>{if(editingText(e)||window.getSelection()?.toString())return;const clip=copyObjects(state,canvas.selection);if(!clip)return;e.preventDefault();e.clipboardData.setData('text/plain',JSON.stringify(clip));toast('Скопировано объектов: '+clip.nodes.length+' · Ctrl+V — вставить')});
document.addEventListener('paste',e=>{if(editingText(e))return;const raw=e.clipboardData?.getData('text/plain');if(!raw||raw.length>3000000)return;let clip;try{clip=JSON.parse(raw)}catch{return}if(clip?.infraLabClipboard!==1)return;e.preventDefault();try{const pasted=pasteObjects(state,clip,CHILDREN,selected),candidate=structuredClone(state);candidate.nodes.push(...pasted.nodes);candidate.links.push(...pasted.links);candidate.wireRoutes=[...(candidate.wireRoutes||[]),...pasted.wireRoutes];validate(candidate);state=candidate;selected=pasted.rootIds.length===1?pasted.rootIds[0]:null;selectedLink=null;canvas.selectedLink=null;canvas.selectedWireRoute=null;canvas.selection=new Set(pasted.rootIds);change();tab('inspect');if(selected)canvas.focus(selected);toast('Вставлено объектов: '+pasted.nodes.length+' · ↶ — отменить')}catch(err){toast('Вставка отклонена: '+err.message)}});
$('inspect').addEventListener('change',e=>{if(e.target.dataset.cluster!==undefined){const n=state.nodes.find(n=>n.id===selected);n.clusterId=e.target.value||undefined;change();return}if(e.target.dataset.linkKey){const l=state.links.find(l=>l.id===selectedLink);const value=e.target.dataset.linkKey==='length'?Number(e.target.value):e.target.value;if(e.target.dataset.linkKey==='length'&&(!Number.isFinite(value)||value<0||value>1e7)){toast('Длина кабеля должна быть числом от 0 до 10000000 м');renderInspect();return}l[e.target.dataset.linkKey]=value;change();return}if(e.target.dataset.member){const n=state.nodes.find(n=>n.id===selected);n.members??=[];if(e.target.checked)n.members.push(e.target.dataset.member);else n.members=n.members.filter(id=>id!==e.target.dataset.member);change();return}const key=e.target.dataset.key;if(!key)return;const n=state.nodes.find(n=>n.id===selected),pi=e.target.closest('[data-interface]');try{let val=e.target.value;if(pi){const p=n.interfaces.find(p=>p.id===pi.dataset.interface);if(key==='prefix'){val=Number(val);if(!Number.isInteger(val)||val<1||val>30)throw Error('Префикс должен быть от 1 до 30')}if(key==='profile'&&!allowedInterfaceProfiles(n,p).includes(val))throw Error('Этот тип интерфейса недопустим для сущности');if(key==='kind'&&!allowedInterfaceProfiles(n,p).some(k=>val==='virtual'?k==='virtual':k!=='virtual'))throw Error('Этот тип адаптера недопустим для сущности');p[key]=physicalValue(key,val);if(key==='profile')p.kind=val==='virtual'?'virtual':'physical';if(key==='kind'){if(val==='virtual')p.profile='virtual';else if(p.profile==='virtual')p.profile='rj45'}if(['ip','prefix','gateway','dns'].includes(key))p.mode='manual'}else if(key==='name'){if(!val.trim())throw Error('Введите название');n.name=val.slice(0,100)}else if(key.includes('.')){const [svc,k]=key.split('.');if(svc==='daemon'&&k==='endpoint'&&!validControlEndpoint(val))throw Error('Endpoint: unix:///run/containerd/containerd.sock или npipe://./pipe/containerd-containerd');if(k==='runtimeId'&&svc==='kubernetes')n.services.kubernetes.runtime=val?'containerd':n.services.kubernetes.runtime;if(k==='records'){val=JSON.parse(val);if(!val||Array.isArray(val)||typeof val!=='object'||Object.entries(val).some(([k,v])=>typeof v!=='string'))throw Error('Ожидается JSON-объект: имя → IP')}if(['start','end','port','publishPort','targetPort','nodePort'].includes(k)){val=Number(val);if(!Number.isInteger(val)||val<1||val>65535)throw Error('Введите целое число от 1 до 65535')}if(k==='nodePort'&&(val<30000||val>32767))throw Error('NodePort должен быть от 30000 до 32767');if(k==='enabled'||k==='ready')val=val==='true';if(k==='routes')val=parseCniRoutes(val);n.services[svc][k]=val}else if(key==='blockICMP')n.rules.blockICMP=val==='true';else if(key==='blockedPorts'){const values=val.split(',').filter(x=>x.trim()).map(Number);if(values.some(x=>!Number.isInteger(x)||x<1||x>65535))throw Error('Неверный TCP-порт');n.rules.blockedPorts=values}change()}catch(err){toast('Ошибка: '+err.message);renderInspect()}});
$('inspect').addEventListener('click',async e=>{const focusEnd=e.target.closest('[data-focus-end]');if(focusEnd){canvas.focus(focusEnd.dataset.focusEnd);return}if(e.target.dataset.failEndpoint||e.target.dataset.restoreEndpoints){const id=e.target.dataset.failEndpoint||e.target.dataset.restoreEndpoints,publications=state.nodes.flatMap(host=>hostPublications(state,host)).filter(p=>p.entity?.id===id);if(e.target.dataset.failEndpoint){const p=publications.find(p=>p.app);if(!p)return toast('Нет готового endpoint');p.app.services.pod.ready=false;toast('Pod '+p.app.name+' → NotReady. Новый запрос выберет другую реплику')}else{for(const c of publications.flatMap(p=>p.candidates))c.pod.services.pod.ready=true;toast('Готовность Pod восстановлена')}change();return}if(e.target.id==='clear-selection'){canvas.selection.clear();selected=null;$('selection-count').textContent='';render();return}if(e.target.id==='delete-selection'){if(await confirmAction('Удалить выделенные объекты и их содержимое? Действие можно отменить.'))removeNodes([...canvas.selection]);return}if(e.target.id==='delete-link'){state.links=state.links.filter(l=>l.id!==selectedLink);selectedLink=null;canvas.selectedLink=null;change();return}const n=state.nodes.find(n=>n.id===selected);if(e.target.id==='add-port'){if(addInterface(n))change()}if(e.target.id==='context-action')menu(n.id,e.clientX-220,e.clientY);if(e.target.dataset.disconnect){state.links=state.links.filter(l=>l.a!==e.target.dataset.disconnect&&l.b!==e.target.dataset.disconnect);change()}if(e.target.id==='delete-node'){if(!await confirmAction('Удалить объект вместе со всеми вложенными нодами и их кабелями? Действие можно отменить кнопкой ↶.'))return;const ids=new Set([n.id]);let old;do{old=ids.size;state.nodes.filter(n=>ids.has(n.parent)).forEach(n=>ids.add(n.id))}while(old!==ids.size);const ports=new Set(state.nodes.filter(n=>ids.has(n.id)).flatMap(n=>n.interfaces.map(p=>p.id)));state.nodes=state.nodes.filter(n=>!ids.has(n.id));state.links=state.links.filter(l=>!ports.has(l.a)&&!ports.has(l.b));state.nodes.forEach(n=>{if(n.members)n.members=n.members.filter(id=>!ports.has(id));if(n.services.http&&ids.has(n.services.http.publishHost))n.services.http.publishHost=''});selected=null;change()}});
function tab(name){$('inspect').hidden=name!=='inspect';$('test').hidden=name!=='test';$('tab-inspect').classList.toggle('active',name==='inspect');$('tab-test').classList.toggle('active',name==='test')}$('tab-inspect').onclick=()=>tab('inspect');$('tab-test').onclick=()=>tab('test');
$('cluster-policy').onclick=()=>{try{if(!localStorage.getItem('infra-lab-backup-before-cluster-policy'))localStorage.setItem('infra-lab-backup-before-cluster-policy',JSON.stringify(state))}catch{return toast('Не удалось сохранить исходную схему')}configureClusterDemo(state);change();canvas.fit();toast('Cluster: worker-01 → Pod worker-02. Проверьте сайт; отказ Pod доступен в свойствах Service')};
$('cluster-demo').onclick=async()=>{if(!await confirmAction('Загрузить демо Proxmox + Kubernetes? Текущая схема сохранится в «До демо».'))return;const next=validate(buildClusterDemo());try{if(state.demoRevision!==5||!localStorage.getItem('infra-lab-backup-before-demo'))localStorage.setItem('infra-lab-backup-before-demo',JSON.stringify(state))}catch{return toast('Не удалось сохранить резервную копию; демо не загружено')}state=next;selected=null;selectedLink=null;canvas.selection.clear();canvas.pending=null;canvas.selectedLink=null;canvas.selectedWireRoute=null;change();canvas.fit();toast('Кластерное демо загружено. Раскройте инструкцию и нажмите «Проверить сайт»')};
$('demo-check').onclick=()=>{$('source').value=state.nodes.find(n=>n.type==='client')?.id;$('target').value=state.demoRequest?.target||'site.lab';$('protocol').value='tcp';$('port').value=state.demoRequest?.port||8080;tab('test');$('run').click()};$('run').onclick=()=>{const port=Number($('port').value);if(!Number.isInteger(port)||port<1||port>65535)return toast('Порт должен быть от 1 до 65535');const request={source:$('source').value,target:$('target').value.trim(),protocol:$('protocol').value,port};player.start(simulate(state,request),request)};
$('dhcp').onclick=()=>{toast(allocate(state).join(' · '));change()};$('auto').onclick=()=>{toast(allocate(state,true).join(' · '));change()};$('add').onclick=e=>{menuPoint={x:80+$('viewport').scrollLeft/canvas.zoom,y:80+$('viewport').scrollTop/canvas.zoom};menu(null,e.clientX,e.clientY)};
$('plus').onclick=()=>canvas.setZoom(canvas.zoom*1.2);$('minus').onclick=()=>canvas.setZoom(canvas.zoom/1.2);$('fit').onclick=()=>canvas.fit();$('zoomtext').onclick=()=>canvas.setZoom(1);$('undo').onclick=undo;$('redo').onclick=redo;
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='infra-lab.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>3000000)throw Error('Файл больше 3 МБ');const imported=validate(JSON.parse(await f.text()));state=imported;selected=null;selectedLink=null;canvas.selectedLink=null;canvas.pending=null;change();toast('Схема восстановлена')}catch(err){toast('Импорт отклонён: '+err.message)}finally{e.target.value=''}};$('restore-backup').onclick=async()=>{if(!await confirmAction('Вернуть схему, сохранённую перед загрузкой демо? Текущее состояние можно вернуть кнопкой ↶.'))return;try{state=validate(JSON.parse(localStorage.getItem('infra-lab-backup-before-demo')));selected=null;selectedLink=null;canvas.pending=null;canvas.selectedLink=null;change();canvas.fit()}catch(err){toast('Не удалось восстановить: '+err.message)}};$('reset').onclick=async()=>{if(await confirmAction('Восстановить демо? Текущую схему можно экспортировать или вернуть кнопкой ↶.')){try{localStorage.setItem('infra-lab-backup-before-demo',JSON.stringify(state))}catch{}state=demo();selected=null;selectedLink=null;canvas.selectedLink=null;canvas.pending=null;change();$('fit').click()}};window.addEventListener('resize',drawWires);settle(state);lastState=JSON.stringify(state);render();save();
